import { junctionLayers, junctionOffset, junctionDiagramScale, compassLayers, clockLayers, dotArrowLayers, eyesLayers, stripkaartLayers, stripkaartHeight, layerRotation } from './hike-sheet.js';

const layerPaths = (layers, rotation = 0) => layers.map(layer => `<path transform="translate(${layer.x ?? 0} ${layer.y ?? 0}) rotate(${layerRotation(layer, rotation)}) scale(${layer.scale ?? 1} ${(layer.scale ?? 1) * (layer.scaleY ?? 1)})" d="${layer.path}" fill="${layer.fill ?? 'none'}"${layer.fillRule ? ` fill-rule="${layer.fillRule}"` : ''} stroke="${layer.width ? layer.color : 'none'}" stroke-width="${layer.width}" stroke-linecap="${layer.cap ?? 'round'}" stroke-linejoin="round"${layer.dash ? ` stroke-dasharray="${layer.dash.join(' ')}"` : ''}/>`).join('');
export const diagram = (element, rotation = 0, placements = [], faintArms = [], wide = false) => { const offset = junctionOffset(element, placements), fit = junctionDiagramScale(element, placements), box = '0 0 100 100'; return `<svg class="junction${wide ? ' step-junction' : ''}" viewBox="${box}" aria-hidden="true"><g transform="rotate(${rotation} 50 50) translate(${offset.x} ${offset.y})"><g transform="translate(50 50) scale(${fit}) translate(-50 -50)">${layerPaths(junctionLayers(element, placements, faintArms), rotation)}</g></g></svg>`; };
export const junctionOverview = element => { const offset = junctionOffset(element); return `<svg class="junction" viewBox="0 0 100 100" aria-hidden="true"><g transform="translate(${offset.x} ${offset.y})">${layerPaths(junctionLayers(element).filter(layer => layer.road))}</g></svg>`; };
export const dotArrowDiagram = (rotation = 0, element) => `<svg class="junction dot-arrow-diagram" viewBox="0 0 100 100" aria-hidden="true"><g transform="rotate(${rotation} 50 50)">${layerPaths(dotArrowLayers(element))}</g></svg>`;
export const eyesDiagram = rotation => `<svg class="junction eyes-diagram" viewBox="0 0 100 100" aria-hidden="true">${layerPaths(eyesLayers(rotation))}</svg>`;
export const stripkaartDiagram = (points,endMarker='arrow') => `<svg class="junction stripkaart-diagram" viewBox="12 0 76 ${stripkaartHeight(points)}" aria-hidden="true">${layerPaths(stripkaartLayers(points,endMarker))}</svg>`;
export const compassDiagram = bearing => `<svg class="junction compass-diagram" viewBox="0 0 100 100" aria-hidden="true">${layerPaths(compassLayers(bearing))}</svg>`;
export const clockDiagram = () => `<svg class="junction clock-diagram" viewBox="0 0 100 100" aria-hidden="true">${layerPaths(clockLayers())}</svg>`;
export const fractionDiagram = (numerator, denominator) => `<svg class="junction fraction-diagram" viewBox="0 0 100 100" aria-hidden="true"><text x="50" y="54" text-anchor="middle" dominant-baseline="middle" fill="#000000" font-family="Arial, sans-serif" font-size="28" font-weight="700">${numerator}/${denominator}</text></svg>`;
export const inputDiagram = () => '<svg class="junction input-diagram" viewBox="0 0 100 100" aria-hidden="true"><rect x="20" y="35" width="60" height="30" rx="3" fill="none" stroke="#000000" stroke-width="3"/><text x="50" y="56" text-anchor="middle" fill="#000000" font-family="Arial, sans-serif" font-size="18" font-weight="700">Aa</text></svg>';
export const quizDiagram = () => '<svg class="junction" viewBox="0 0 100 100" aria-hidden="true"><text x="50" y="57" text-anchor="middle" fill="#000000" font-family="Arial, sans-serif" font-size="23" font-weight="700">A B C</text></svg>';
export const photoDiagram = source => source ? `<img class="junction photo-diagram" src="${String(source).replace(/"/g, '&quot;')}" alt="">` : '<svg class="junction photo-diagram" viewBox="0 0 100 100" aria-hidden="true"><rect x="20" y="28" width="60" height="44" rx="4" fill="none" stroke="#000000" stroke-width="3"/><circle cx="38" cy="43" r="5" fill="#000000"/><path d="M24 66L42 50L52 59L60 51L76 66" fill="none" stroke="#000000" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>';
